// Из доступной документации @jinx-ui/react подтверждён только JxButton,
// поэтому остальные элементы собраны на разметке + токенах var(--jx-*).
import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

type Status = 'active' | 'paused' | 'over';

type Project = {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: Status;
};

const PAGE_SIZE = 5;

const ALL_STATUSES: Status[] = ['active', 'paused', 'over'];

const STATUS_LABEL: Record<Status, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышение',
};

const STATUS_COLOR: Record<Status, string> = {
  active: 'var(--jx-color-success)',
  paused: 'var(--jx-color-text-muted)',
  over: 'var(--jx-color-danger)',
};

const PROJECTS: Project[] = [
  { id: 'atlas', name: 'Atlas', spent: 18400, quota: 40000, status: 'active' },
  { id: 'beacon', name: 'Beacon', spent: 39200, quota: 40000, status: 'active' },
  { id: 'cinder', name: 'Cinder', spent: 6100, quota: 25000, status: 'paused' },
  { id: 'delta', name: 'Delta Ingest', spent: 51000, quota: 45000, status: 'over' },
  { id: 'ember', name: 'Ember', spent: 12750, quota: 30000, status: 'active' },
  { id: 'forge', name: 'Forge', spent: 0, quota: 15000, status: 'paused' },
  { id: 'gale', name: 'Gale Analytics', spent: 28900, quota: 30000, status: 'active' },
  { id: 'harbor', name: 'Harbor', spent: 9400, quota: 20000, status: 'paused' },
  { id: 'iris', name: 'Iris', spent: 61200, quota: 50000, status: 'over' },
  { id: 'juno', name: 'Juno', spent: 4300, quota: 18000, status: 'active' },
  { id: 'kilo', name: 'Kilo Search', spent: 22100, quota: 35000, status: 'active' },
  { id: 'lumen', name: 'Lumen', spent: 16800, quota: 16000, status: 'over' },
  { id: 'mistral', name: 'Mistral', spent: 3200, quota: 22000, status: 'paused' },
];

const RADIUS = 18;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

const money = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

export default function ProjectSpendPanel() {
  const [selected, setSelected] = useState<Status[]>(ALL_STATUSES);
  const [page, setPage] = useState(0);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => selected.includes(project.status)),
    [selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount - 1);
  const rows = filtered.slice(currentPage * PAGE_SIZE, currentPage * PAGE_SIZE + PAGE_SIZE);

  const toggleStatus = (status: Status) => {
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(0);
  };

  const resetFilters = () => {
    setSelected(ALL_STATUSES);
    setPage(0);
  };

  return (
    <section
      aria-label="Расход по проектам"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4, 16px)',
        padding: 'var(--jx-space-4, 16px)',
        borderRadius: 'var(--jx-radius-lg, 12px)',
        border: '1px solid var(--jx-color-border)',
        background: 'var(--jx-color-surface)',
        color: 'var(--jx-color-text)',
      }}
    >
      <div
        role="group"
        aria-label="Фильтр по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2, 8px)' }}
      >
        {ALL_STATUSES.map((status) => {
          const isOn = selected.includes(status);
          return (
            <button
              key={status}
              type="button"
              aria-pressed={isOn}
              onClick={() => toggleStatus(status)}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1, 6px)',
                padding: 'var(--jx-space-1, 4px) var(--jx-space-3, 12px)',
                borderRadius: 'var(--jx-radius-pill, 999px)',
                border: '1px solid currentColor',
                cursor: 'pointer',
                font: 'inherit',
                fontSize: 'var(--jx-font-size-sm, 0.875rem)',
                color: isOn ? STATUS_COLOR[status] : 'var(--jx-color-text-muted)',
                background: isOn ? 'var(--jx-color-surface-raised)' : 'transparent',
                opacity: isOn ? 1 : 0.65,
              }}
            >
              <span>{STATUS_LABEL[status]}</span>
              <span aria-hidden="true">{isOn ? '×' : '+'}</span>
            </button>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 'var(--jx-space-3, 12px)',
            padding: 'var(--jx-space-6, 32px) var(--jx-space-4, 16px)',
            textAlign: 'center',
            borderRadius: 'var(--jx-radius-md, 8px)',
            border: '1px dashed var(--jx-color-border)',
          }}
        >
          <p style={{ margin: 0, fontWeight: 600 }}>Нет проектов под выбранные фильтры</p>
          <p style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}>
            Снятые статусы скрыли все строки.
          </p>
          <JxButton variant="primary" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        </div>
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--jx-space-2, 8px)',
            }}
          >
            {rows.map((project) => {
              const percent = Math.round((project.spent / project.quota) * 100);
              const dashOffset = CIRCUMFERENCE * (1 - Math.min(percent, 100) / 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 'var(--jx-space-3, 12px)',
                    padding: 'var(--jx-space-3, 12px)',
                    borderRadius: 'var(--jx-radius-md, 8px)',
                    border: '1px solid var(--jx-color-border)',
                  }}
                >
                  <span
                    role="img"
                    aria-label={`Квота израсходована на ${percent} процентов`}
                    style={{
                      position: 'relative',
                      display: 'inline-flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: STATUS_COLOR[project.status],
                    }}
                  >
                    <svg width={44} height={44} viewBox="0 0 44 44" aria-hidden="true">
                      <circle
                        cx={22}
                        cy={22}
                        r={RADIUS}
                        fill="none"
                        strokeWidth={4}
                        stroke="var(--jx-color-border)"
                      />
                      <circle
                        cx={22}
                        cy={22}
                        r={RADIUS}
                        fill="none"
                        strokeWidth={4}
                        strokeLinecap="round"
                        stroke="currentColor"
                        strokeDasharray={CIRCUMFERENCE}
                        strokeDashoffset={dashOffset}
                        transform="rotate(-90 22 22)"
                      />
                    </svg>
                    <span
                      aria-hidden="true"
                      style={{
                        position: 'absolute',
                        fontSize: 'var(--jx-font-size-xs, 0.6875rem)',
                        fontWeight: 600,
                      }}
                    >
                      {percent}%
                    </span>
                  </span>

                  <span style={{ display: 'flex', flexDirection: 'column', flex: 1, minWidth: 0 }}>
                    <span
                      style={{
                        fontWeight: 600,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </span>
                    <span
                      style={{
                        color: 'var(--jx-color-text-muted)',
                        fontSize: 'var(--jx-font-size-sm, 0.875rem)',
                      }}
                    >
                      {money.format(project.spent)} из {money.format(project.quota)}
                    </span>
                  </span>

                  <span
                    style={{
                      padding: 'var(--jx-space-1, 4px) var(--jx-space-2, 8px)',
                      borderRadius: 'var(--jx-radius-pill, 999px)',
                      border: '1px solid currentColor',
                      color: STATUS_COLOR[project.status],
                      fontSize: 'var(--jx-font-size-sm, 0.875rem)',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {STATUS_LABEL[project.status]}
                  </span>
                </li>
              );
            })}
          </ul>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 'var(--jx-space-3, 12px)',
            }}
          >
            <span
              aria-live="polite"
              style={{
                color: 'var(--jx-color-text-muted)',
                fontSize: 'var(--jx-font-size-sm, 0.875rem)',
              }}
            >
              Страница {currentPage + 1} из {pageCount} · {filtered.length} проектов
            </span>
            <span style={{ display: 'flex', gap: 'var(--jx-space-2, 8px)' }}>
              <JxButton
                onClick={() => setPage(Math.max(0, currentPage - 1))}
                disabled={currentPage === 0}
              >
                Назад
              </JxButton>
              <JxButton
                onClick={() => setPage(Math.min(pageCount - 1, currentPage + 1))}
                disabled={currentPage >= pageCount - 1}
              >
                Вперёд
              </JxButton>
            </span>
          </div>
        </>
      )}
    </section>
  );
}

